// =====================================================================
// VALIDATE ITEMS
//
// Body: { items: [{ sku, itemId }] }
// READ-ONLY proxy — the only eBay call downstream is GetItem. Rejects a
// malformed or oversized batch before any network spend. Apps Script caps
// at 120 (LOCATION_UPDATE.fetchCap); this is the independent server-side
// guard — a guard that lives only in the caller is a guard a future
// caller forgets.
// =====================================================================

const body = $input.first().json.body || $input.first().json;
const rawItems = Array.isArray(body.items) ? body.items : [];

if (rawItems.length === 0) {
  throw new Error('No items in request body — expected { items: [{sku, itemId}] }');
}

const MAX = 150;  // hard server-side cap (Apps Script caps lower, 120)
if (rawItems.length > MAX) {
  throw new Error('Batch too large (' + rawItems.length + ') — hard cap is ' + MAX + ' per call');
}

const valid = [];
const prefailed = [];

for (const it of rawItems) {
  const sku = String((it && it.sku) || '').trim();
  const itemId = String((it && it.itemId) || '').trim();

  if (!sku) continue;  // nothing to key the result on — drop silently
  if (!/^\d{6,}$/.test(itemId)) {
    prefailed.push({ sku, itemId, ok: false, location: '', error: 'missing/invalid itemId' });
    continue;
  }
  valid.push({ sku, itemId });
}

if (valid.length === 0 && prefailed.length === 0) {
  throw new Error('No usable items in request body');
}

return [{ json: { valid, prefailed } }];

// =====================================================================
// GETITEM LOCATIONS — the item's physical location, LIVE from eBay
//
// The business stores each item's warehouse location in the "Model Year"
// item specific on the eBay listing (the same field MAIN's sync mirrors
// into Master Inventory's "C:Model Year" column). This node calls Trading
// API GetItem per item and extracts that one value.
//
// Chunked-parallel (5 at a time, 200ms between chunks) — same helper the
// eBay orders workflow's node 8.5 uses per order batch, gentled for the
// larger batches a whole-sheet check can send. Per-item try/catch so one
// dead listing never aborts the batch.
//
// ⚠ REGEX NOTE (CLAUDE.md Gotchas #14/#15): every tag match uses a LITERAL
// regex with \b word-boundary — eBay returns attributed tags
// (<CurrentPrice currencyID=...>) and <Name> must not match <NameValueList>.
// Never rebuild these with new RegExp(`...`) — string-built regexes need
// double-escaped backslashes and have bitten this project twice.
// =====================================================================

const LOCATION_SPECIFIC = 'Model Year';   // the item specific that holds the location
const CHUNK = 5;

const token = $('🔑 Get eBay Access Token').first().json.access_token;
if (!token) throw new Error('Get eBay Access Token returned no access_token — check the Basic auth + refresh token pasted into that node');

const input = $('✅ Validate Items').first().json;
const valid = input.valid || [];
const results = (input.prefailed || []).slice();

const headers = {
  'X-EBAY-API-CALL-NAME':           'GetItem',
  'X-EBAY-API-COMPATIBILITY-LEVEL': '967',
  'X-EBAY-API-SITEID':              '0',
  'X-EBAY-API-IAF-TOKEN':           token,
  'Content-Type':                   'text/xml'
};

const decodeEntities = (s) => String(s)
  .replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"').replace(/&#0?39;/g, "'").replace(/&apos;/g, "'");

const getOne = async (it) => {
  const body = '<?xml version="1.0" encoding="utf-8"?>\n' +
    '<GetItemRequest xmlns="urn:ebay:apis:eBLBaseComponents">' +
    '<ItemID>' + it.itemId + '</ItemID>' +
    '<DetailLevel>ReturnAll</DetailLevel>' +
    '<IncludeItemSpecifics>true</IncludeItemSpecifics>' +
    '</GetItemRequest>';

  try {
    const xml = await this.helpers.httpRequest({
      method:  'POST',
      url:     'https://api.ebay.com/ws/api.dll',
      headers,
      body,
      timeout: 15000
    });

    const ackMatch = String(xml).match(/<Ack\b[^>]*>([\s\S]*?)<\/Ack>/);
    const ack = ackMatch ? ackMatch[1] : '';
    if (ack !== 'Success' && ack !== 'Warning') {
      const shortMsg = String(xml).match(/<ShortMessage\b[^>]*>([\s\S]*?)<\/ShortMessage>/);
      return { sku: it.sku, itemId: it.itemId, ok: false, location: '',
               error: 'GetItem Ack=' + (ack || 'none') + (shortMsg ? ' — ' + shortMsg[1] : '') };
    }

    // Walk the NameValueList blocks for the location specific.
    // <Name\b will NOT match <NameValueList> (V is a word char → no boundary).
    let location = '';
    const blocks = String(xml).match(/<NameValueList\b[^>]*>[\s\S]*?<\/NameValueList>/g) || [];
    for (const block of blocks) {
      const nameMatch = block.match(/<Name\b[^>]*>([\s\S]*?)<\/Name>/);
      if (!nameMatch || decodeEntities(nameMatch[1]).trim() !== LOCATION_SPECIFIC) continue;
      const valueMatch = block.match(/<Value\b[^>]*>([\s\S]*?)<\/Value>/);
      if (valueMatch) location = decodeEntities(valueMatch[1]).trim();
      break;
    }

    return { sku: it.sku, itemId: it.itemId, ok: true, location, error: '' };
  } catch (e) {
    const msg = (e && e.message) ? e.message : String(e);
    return { sku: it.sku, itemId: it.itemId, ok: false, location: '', error: msg.slice(0, 200) };
  }
};

for (let i = 0; i < valid.length; i += CHUNK) {
  const chunk = valid.slice(i, i + CHUNK);
  const settled = await Promise.all(chunk.map(getOne));
  for (const r of settled) results.push(r);
  if (i + CHUNK < valid.length) await new Promise(r => setTimeout(r, 200));
}

const okCount = results.filter(r => r.ok).length;
console.log(`📍 Location check: ${okCount} ok, ${results.length - okCount} failed of ${results.length}`);

return [{ json: { ok: true, count: results.length, results } }];
